ue,"validation":{"minSelected":1}},{"name":"experienceSummary","type":"textarea","labelAm":"ቀደም ሲል የነበሩዎት የበጎ ፈቃድ ወይም የአገልግሎት ልምዶች","labelEn":"Previous Volunteer or Service Experience","required":true,"validation":{"maxLength":1000,"minLength":10}},{"name":"hasConfessionFather","type":"radio","labelAm":"የንስሐ አባት አሎት?","labelEn":"Do you have a confession father?","options":[{"value":"yes","labelAm":"አዎ አለኝ","labelEn":"Yes"},{"value":"no","labelAm":"እስካሁን የለኝም","labelEn":"Not yet"}],"required":true},{"name":"recommendationLetter","type":"file","labelAm":"የድጋፍ ወይም የደብር ደብዳቤ (ካለዎት)","labelEn":"Recommendation Letter (Optional)","required":false}],"titleAm":"የበጎ ፈቃድ አገልግሎት ምዝገባ ቅጽ","titleEn":"Volunteer Ministry Sign-Up Form","descriptionAm":"ለቤተ ክርስቲያንና ለወገን በበጎ ፈቃድ ለማገልገል ይመዝገቡ","descriptionEn":"Register to serve the church and community as a volunteer"},"description":"በሰንበት ትምህርት ቤቱ በተለያዩ የበጎ አድራጎት፣ የልማትና የማኅበራዊ አገልግሎት ዘርፎች ለመሳተፍ የተዘጋጀ ቅጽ","allowOneResponsePerMember":false}', '127.0.0.1', '2026-10-13T08:02:37.634Z');
