INSERT INTO `courses` (`id`, `titleAm`, `titleEn`, `description`, `level`, `teacherId`, `schedule`, `capacity`, `startDate`, `endDate`, `status`, `createdAt`, `updatedAt`) VALUES ('05dafc55-b15d-4879-a02a-3dff185a7256', 'ያሬዳዊ ዜማና የከበሮ አመታት', 'Saint Yared Hymnody & Liturgical Rhythms', 'የቅዱስ ያሬድ ዜማ ሥርዓት (ግዕዝ፣ ዕዝል፣ አራራይ) እና የዝማሬ መሣሪያዎች አጠቃቀም', 'ደረጃ ፫', '63f8b91b-e87c-451d-98ba-1c76a653f3c2', 'እሑድ ጠዋት 2:00 - 4:00', 25, '2026-09-01T00:00:00.000Z', '2027-06-30T00:00:00.000Z', 'open', '2026-10-12T12:37:40.561Z', '2026-10-12T12:37:40.561Z');
