INSERT INTO `courses` (`id`, `titleAm`, `titleEn`, `description`, `level`, `teacherId`, `schedule`, `capacity`, `startDate`, `endDate`, `status`, `createdAt`, `updatedAt`) VALUES ('84355264-d6f5-4d0a-b652-284776e972e4', 'የመጽሐፍ ቅዱስ ጥናት ፩ (ኦሪትና ታሪክ)', 'Biblical Studies I (Pentateuch & History)', 'ከኦሪት ዘፍጥረት እስከ ነቢያት መጻሕፍት ያለው ጥልቅ መንፈሳዊ ትንታኔና የትርጓሜ ጥናት', 'ደረጃ ፩', '63f8b91b-e87c-451d-98ba-1c76a653f3c2', 'ቅዳሜ ከሰዓት 8:00 - 10:00', 40, '2026-09-01T00:00:00.000Z', '2027-06-30T00:00:00.000Z', 'open', '2026-10-12T12:37:40.038Z', '2026-10-12T12:37:40.038Z');
