INSERT INTO `courses` (`id`, `titleAm`, `titleEn`, `description`, `level`, `teacherId`, `schedule`, `capacity`, `startDate`, `endDate`, `status`, `createdAt`, `updatedAt`) VALUES ('a187a196-2cb7-42d7-90e1-f1d3d059f52d', 'የግዕዝ ቋንቋ መሠረታዊ ጥናት', 'Introduction to Ge\'ez Language', 'የግዕዝ ፊደላት፣ ሰዋስው፣ ቃላት ግንባታና የጸሎት መጻሕፍት ንባብ', 'ደረጃ ፩', '63f8b91b-e87c-451d-98ba-1c76a653f3c2', 'ቅዳሜ ጠዋት 3:00 - 5:00', 30, '2026-09-01T00:00:00.000Z', '2027-06-30T00:00:00.000Z', 'open', '2026-10-12T12:37:40.446Z', '2026-10-12T12:37:40.446Z');
INSERT INTO `courses` (`id`, `titleAm`, `titleEn`, `description`, `level`, `teacherId`, `schedule`, `capacity`, `startDate`, `endDate`, `status`, `createdAt`, `updatedAt`) VALUES ('f9b50afd-a429-494d-9a45-98f2b5a79012', 'ነገረ ማርያም (Mariology)', 'Mariology: The Mystery of the Theotokos', 'የእመቤታችን ቅድስት ድንግል ማርያም ዘላለማዊ ድንግልና፣ አማላጅነትና ክብረ ቅድስና', 'ደረጃ ፪', '63f8b91b-e87c-451d-98ba-1c76a653f3c2', 'ረቡዕ ማታ 12:00 - 1:30', 50, '2026-09-01T00:00:00.000Z', '2027-06-30T00:00:00.000Z', 'open', '2026-10-12T12:37:40.316Z', '2026-10-12T12:37:40.316Z');
INSERT INTO `departments` (`id`, `nameAm`, `nameEn`, `description`, `createdAt`, `updatedAt`) VALUES (1, 'መዝሙር ክፍል', 'Choir & Hymnology Department', 'የያሬዳዊ ዜማና ቅዱሳት መዝሙራት ትምህርትና አገልግሎት ማስተባበሪያ ክፍል', '2026-10-12T12:24:26.257Z', '2026-10-13T08:38:00.271Z');
INSERT INTO `departments` (`id`, `nameAm`, `nameEn`, `description`, `createdAt`, `updatedAt`) VALUES (2, 'ትምህርት ክፍል', 'Education Department', 'የነገረ መለኮት፣ የመጽሐፍ ቅዱስና የቤተ ክርስቲያን ሥርዓት ትምህርቶች ክፍል', '2026-10-12T12:24:26.279Z', '2026-10-13T08:38:00.293Z');
INSERT INTO `departments` (`id`, `nameAm`, `nameEn`, `description`, `createdAt`, `updatedAt`) VALUES (3, 'ማኅበራዊ አገልግሎት ክፍል', 'Social Service Department', 'የበጎ አድራጎት፣ የልማትና የእርስ በእርስ መረዳዳት አገልግሎት ክፍል', '2026-10-12T12:24:26.298Z', '2026-10-13T08:38:00.316Z');
INSERT INTO `departments` (`id`, `nameAm`, `nameEn`, `description`, `createdAt`, `updatedAt`) VALUES (4, 'ህፃናት ክፍል', 'Children Ministry Department', 'የህፃናት መንፈሳዊ አስተዳደግ፣ ትምህርትና መርሐ ግብራት ክፍል', '2026-10-12T12:24:26.318Z', '2026-10-13T08:38:00.341Z');
INSERT INTO `departments` (`id`, `nameAm`, `nameEn`, `description`, `createdAt`, `updatedAt`) VALUES (5, 'ወጣቶች ክፍል', 'Youth Fellowship Department', 'የወጣቶች መንፈሳዊ ሕይወት ግንባታ፣ ውይይትና የሕብረት አገልግሎት ክፍል', '2026-10-12T12:24:26.340Z', '2026-10-13T08:38:00.363Z');
