INSERT INTO `events` (`id`, `title`, `description`, `location`, `startAt`, `endAt`, `capacity`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('0068df57-1b08-4dbf-91db-e740899c1bcd', 'የወጣቶች መንፈሳዊ ሲምፖዚየም', 'ወጣቱ በዘመናዊው ዓለም ውስጥ ያለውን የክርስትና ማንነት ለመጠበቅ የሚደረግ ውይይት', 'የሰንበት ት/ቤት ትልቁ አዳራሽ', '2026-11-08T14:00:00.000Z', '2026-11-08T18:00:00.000Z', 150, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.945Z', '2026-10-12T12:37:42.945Z');
