INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `createdBy`, `createdAt`, `updatedAt`, `allowOneResponsePerMember`) VALUES ('220efd51-2818-4938-9021-d12e97cb1629', 'የ2019 ልዩ መንፈሳዊ ጉባኤና የአባላት ዳሰሳ ቅጽ', 'የአባላት የተሳትፎና የአገልግሎት ዝግጁነት መመዝገቢያ ቅጽ', '{"fields":[{"name":"spiritualName","type":"text","labelAm":"የክርስትና ስም","labelEn":"Baptismal Name","required":true,"validation":{"maxLength":50,"minLength":3}},{"name":"reflection","type":"textarea","labelAm":"የመንፈሳዊ ሕይወት አስተያየት","labelEn":"Spiritual Life Reflection","required":true,"validation":{"minLength":10}},{"name":"serviceYears","type":"number","labelAm":"በሰንበት ት/ቤት ያገለገሉበት ዓመታት","labelEn":"Years in Ministry","required":true,"validation":{"max":40,"min":1}},{"name":"registrationDate","type":"date","labelAm":"የምዝገባ ቀን","labelEn":"Registration Date","required":true,"validation":{"minDate":"2026-01-01"}},{"name":"departmentChoice","type":"dropdown","labelAm":"የተመረጠ የአገልግሎት ዘርፍ","labelEn":"Chosen Ministry","options":[{"value":"ትምህርት","labelAm":"የትምህርት ክፍል"},{"value":"መዝሙር","labelAm":"የመዝሙር ክፍል"},{"value":"ልማት","labelAm":"የልማት ክፍል"}],"required":true},{"name":"shiftPreference","type":"radio","labelAm":"የአገልግሎት ሰዓት ምርጫ","labelEn":"Shift Preference","options":[{"value":"ጧት","labelAm":"የጧት መርሐ ግብር"},{"value":"ከሰዓት","labelAm":"የከሰዓት መርሐ ግብር"}],"required":true},{"name":"availableDays","type":"checkbox","labelAm":"የሚገኙባቸው ቀናት","labelEn":"Available Days","options":[{"value":"ቅዳሜ","labelAm":"ቅዳሜ"},{"value":"እሑድ","labelAm":"እሑድ"}],"required":true,"validation":{"minSelected":1}},{"name":"receiptFile","type":"file","labelAm":"የተሳትፎ ክፍያ ደረሰኝ","labelEn":"Participation Receipt Slip","required":true}],"titleAm":"የ2019 ልዩ መንፈሳዊ ጉባኤና የአባላት ዳሰሳ ቅጽ","titleEn":"Annual Spiritual Conference & Member Survey"}', 'open', '2026-12-31T23:59:59.000Z', '1a7ec929-3f61-4173-87d7-3d0ba1961c3e', '2026-10-13T08:12:58.222Z', '2026-10-13T08:12:58.222Z', 0);
INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `createdBy`, `createdAt`, `updatedAt`, `allowOneResponsePerMember`) VALUES ('3153cb98-4e04-45e1-9909-573e765b67eb', 'የሰንበት ትምህርት ቤት አገልግሎት እርካታ መጠይቅ ቅጽ', 'የአገልግሎታችንን ጥራት ለማሻሻል ከአባላትና ከምእመናን ግብረ-መልስ የሚሰበሰብበት የዳሰሳ ጥናት', '{"fields":[{"name":"respondentRole","type":"dropdown","labelAm":"በሰንበት ት/ቤቱ ያለዎት ሚና","labelEn":"Role","options":[{"value":"member","labelAm":"ተማሪ / አባል"},{"value":"parent","labelAm":"ወላጅ"}],"required":true},{"name":"overallSatisfaction","type":"radio","labelAm":"አጠቃላይ እርካታ","labelEn":"Satisfaction","options":[{"value":"very_satisfied","labelAm":"በጣም ከፍተኛ"},{"value":"satisfied","labelAm":"ከፍተኛ"}],"required":true},{"name":"spiritualLessonsRating","type":"number","labelAm":"የትምህርት ጥራት (1-5)","labelEn":"Lessons Rating","required":true,"validation":{"max":5,"min":1}},{"name":"punctualityRating","type":"number","labelAm":"የሰዓት አከባበር (1-5)","labelEn":"Punctuality","required":true,"validation":{"max":5,"min":1}},{"name":"improvementSuggestions","type":"textarea","labelAm":"መሻሻል አለባቸው የሚሏቸው ጉዳዮች","labelEn":"Improvement Suggestions","required":true,"validation":{"minLength":5}}],"titleAm":"የሰንበት ትምህርት ቤት አገልግሎት እርካታ መጠይቅ ቅጽ","titleEn":"Sunday School Service Satisfaction Survey"}', 'open', '2026-12-31T23:59:59.000Z', '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-13T07:44:12.331Z', '2026-10-13T07:44:12.331Z', 1);
INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `createdBy`, `createdAt`, `updatedAt`, `allowOneResponsePerMember`) VALUES ('33403ec2-362d-40f5-8b49-bc01c3888034', 'የ2019 ልዩ መንፈሳዊ ጉባኤና የአባላት ዳሰሳ ቅጽ', 'የአባላት የተሳትፎና የአገልግሎት ዝግጁነት መመዝገቢያ ቅጽ', '{"fields":[{"name":"spiritualName","type":"text","labelAm":"የክርስትና ስም","labelEn":"Baptismal Name","required":true,"validation":{"maxLength":50,"minLength":3}},{"name":"reflection","type":"textarea","labelAm":"የመንፈሳዊ ሕይወት አስተያየት","labelEn":"Spiritual Life Reflection","required":true,"validation":{"minLength":10}},{"name":"serviceYears","type":"number","labelAm":"በሰንበት ት/ቤት ያገለገሉበት ዓመታት","labelEn":"Years in Ministry","required":true,"validation":{"max":40,"min":1}},{"name":"registrationDate","type":"date","labelAm":"የምዝገባ ቀን","labelEn":"Registration Date","required":true,"validation":{"minDate":"2026-01-01"}},{"name":"departmentChoice","type":"dropdown","labelAm":"የተመረጠ የአገልግሎት ዘርፍ","labelEn":"Chosen Ministry","options":[{"value":"ትምህርት","labelAm":"የትምህርት ክፍል"},{"value":"መዝሙር","labelAm":"የመዝሙር ክፍል"},{"value":"ልማት","labelAm":"የልማት ክፍል"}],"required":true},{"name":"shiftPreference","type":"radio","labelAm":"የአገልግሎት ሰዓት ምርጫ","labelEn":"Shift Preference","options":[{"value":"ጧት","labelAm":"የጧት መርሐ ግብር"},{"value":"ከሰዓት","labelAm":"የከሰዓት መርሐ ግብር"}],"required":true},{"name":"availableDays","type":"checkbox","labelAm":"የሚገኙባቸው ቀናት","labelEn":"Available Days","options":[{"value":"ቅዳሜ","labelAm":"ቅዳሜ"},{"value":"እሑድ","labelAm":"እሑድ"}],"required":true,"validation":{"minSelected":1}},{"name":"receiptFile","type":"file","labelAm":"የተሳትፎ ክፍያ ደረሰኝ","labelEn":"Participation Receipt Slip","required":true}],"titleAm":"የ2019 ልዩ መንፈሳዊ ጉባኤና የአባላት ዳሰሳ ቅጽ","titleEn":"Annual Spiritual Conference & Member Survey"}', 'open', '2026-12-31T23:59:59.000Z', '1a7ec929-3f61-4173-87d7-3d0ba1961c3e', '2026-10-13T08:02:37.708Z', '2026-10-13T08:02:37.708Z', 0);
