INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `createdBy`, `createdAt`, `updatedAt`, `allowOneResponsePerMember`) VALUES ('4c1df606-5566-4417-87e2-3f6e43094631', 'የበጎ ፈቃድ አገልግሎት ምዝገባ ቅጽ', 'በሰንበት ትምህርት ቤቱ በተለያዩ የበጎ አድራጎት፣ የልማትና የማኅበራዊ አገልግሎት ዘርፎች ለመሳተፍ የተዘጋጀ ቅጽ', '{"fields":[{"name":"volunteerName","type":"text","labelAm":"የበጎ ፈቃደኛው ሙሉ ስም","labelEn":"Volunteer Full Name","required":true,"validation":{"minLength":3}},{"name":"phone","type":"text","labelAm":"ስልክ ቁጥር","labelEn":"Phone Number","required":true,"validation":{"minLength":9}},{"name":"profession","type":"text","labelAm":"የትምህርት ደረጃ ወይም ሙያዊ መስክ","labelEn":"Education or Profession","required":true},{"name":"interestedMinistries","type":"checkbox","labelAm":"ለማገልገል የሚፈልጓቸው ዘርፎች (ቢያንስ አንድ ይምረጡ)","labelEn":"Interested Ministry Fields","options":[{"value":"media","labelAm":"ሚዲያ፣ ድረ-ገጽና ቴክኖሎጂ","labelEn":"Media & Technology"},{"value":"children","labelAm":"የሕፃናትና ታዳጊዎች ማስተማር","labelEn":"Children Teaching"},{"value":"cleaning_order","labelAm":"የቤተ መቅደስ ጽዳትና ሥርዓት ማስከበር","labelEn":"Sanctuary Care & Protocol"},{"value":"medical_aid","labelAm":"የሕክምናና የመጀመሪያ እርዳታ ድጋፍ","labelEn":"First Aid & Health Ministry"},{"value":"charity","labelAm":"የአረጋውያንና ችግረኞች መርጃ ማዕድ","labelEn":"Charity & Food Outreach"}],"required":true,"validation":{"minSelected":1}},{"name":"availableDays","type":"checkbox","labelAm":"የሚያገለግሉባቸው አመቺ ቀናት","labelEn":"Available Days","options":[{"value":"sat_afternoon","labelAm":"ቅዳሜ ከሰዓት","labelEn":"Saturday Afternoon"},{"value":"sun_morning","labelAm":"እሑድ ጠዋት","labelEn":"Sunday Morning"},{"value":"sun_afternoon","labelAm":"እሑድ ከሰዓት","labelEn":"Sunday Afternoon"},{"value":"holidays","labelAm":"በዓበይት በዓላት ቀናት","labelEn":"On Major Feast Days"}],"required":true,"validation":{"minSelected":1}},{"name":"experienceSummary","type":"textarea","labelAm":"ቀደም ሲል የነበሩዎት የበጎ ፈቃድ ወይም የአገልግሎት ልምዶች","labelEn":"Previous Volunteer or Service Experience","required":true,"validation":{"maxLength":1000,"minLength":10}},{"name":"hasConfessionFather","type":"radio","labelAm":"የንስሐ አባት አሎት?","labelEn":"Do you have a confession father?","options":[{"value":"yes","labelAm":"አዎ አለኝ","labelEn":"Yes"},{"value":"no","labelAm":"እስካሁን የለኝም","labelEn":"Not yet"}],"required":true},{"name":"recommendationLetter","type":"file","labelAm":"የድጋፍ ወይም የደብር ደብዳቤ (ካለዎት)","labelEn":"Recommendation Letter (Optional)","required":false}],"titleAm":"የበጎ ፈቃድ አገልግሎት ምዝገባ ቅጽ","titleEn":"Volunteer Ministry Sign-Up Form","descriptionAm":"ለቤተ ክርስቲያንና ለወገን በበጎ ፈቃድ ለማገልገል ይመዝገቡ","descriptionEn":"Register to serve the church and community as a volunteer"}', 'open', NULL, '1a7ec929-3f61-4173-87d7-3d0ba1961c3e', '2026-10-13T08:02:37.510Z', '2026-10-13T08:02:37.510Z', 0);
INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `createdBy`, `createdAt`, `updatedAt`, `allowOneResponsePerMember`) VALUES ('670b5efd-2e11-4a62-a8b6-870a22329a4b', 'የጊዜ ገደቡ ያለፈበት ቅጽ (Expired)', NULL, '{"fields":[{"name":"test","type":"text","labelAm":"ፈተና","required":true}]}', 'open', '2020-01-01T00:00:00.000Z', '1a7ec929-3f61-4173-87d7-3d0ba1961c3e', '2026-10-13T08:12:58.569Z', '2026-10-13T08:12:58.569Z', 0);
INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `createdBy`, `createdAt`, `updatedAt`, `allowOneResponsePerMember`) VALUES ('6df1f01a-3d99-45b5-84b7-931271c12b0b', 'የአዲስ ተማሪዎች ምዝገባ ቅጽ (2019 ዓ.ም)', 'ወደ ሰንበት ትምህርት ቤቱ አዲስ ለሚገቡ ተማሪዎች የተዘጋጀ የመመዝገቢያ ቅጽ', '{"fields":[{"name":"fullName","type":"text","label":"ሙሉ ስም","required":true},{"name":"baptismalName","type":"text","label":"የክርስትና ስም","required":true},{"name":"age","type":"number","label":"ዕድሜ","required":true},{"name":"departmentInterest","type":"select","label":"የሚፈልጉት የአገልግሎት ክፍል","options":["ትምህርት","መዝሙር","ልማት"]}]}', 'open', '2026-12-31T00:00:00.000Z', '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:43.257Z', '2026-10-12T12:37:43.257Z', 0);
INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `createdBy`, `createdAt`, `updatedAt`, `allowOneResponsePerMember`) VALUES ('6e14d7dd-fb33-47f4-a643-7208c5879b96', 'የአባላት አስተያየትና መጠይቅ ቅጽ', 'የሰንበት ትምህርት ቤቱን አገልግሎት ለማሻሻል የቀረበ የዳሰሳ ጥናት', '{"fields":[{"max":5,"min":1,"name":"satisfaction","type":"rating","label":"በትምህርቱ አገልግሎት ምን ያህል ረክተዋል?"},{"name":"suggestions","type":"textarea","label":"ተጨማሪ አስተያየትና ማሻሻያ ሀሳብ","required":false}]}', 'open', '2026-12-31T00:00:00.000Z', '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:43.305Z', '2026-10-12T12:37:43.305Z', 0);
INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `createdBy`, `createdAt`, `updatedAt`, `allowOneResponsePerMember`) VALUES ('6eed9fa5-0fe7-4682-957f-8c4c3a43ebff', 'የስእለትና የልማት ቃል ኪዳን መመዝገቢያ ቅጽ', 'ለቤተ ክርስቲያንና ሰንበት ትምህርት ቤት ሕንፃ፣ መጻሕፍት ሕትመትና ልማት የሚደረግ የገንዘብ ቃል ኪዳን መመዝገቢያ', '{"fields":[{"name":"pledgerName","type":"text","labelAm":"የሰጪው ሙሉ ስም","labelEn":"Pledger Name","required":true},{"name":"phone","type":"text","labelAm":"ስልክ ቁጥር","labelEn":"Phone Number","required":true},{"name":"pledgePurpose","type":"dropdown","labelAm":"የስእለት ዓላማ","labelEn":"Purpose","options":[{"value":"building","labelAm":"ለሕንፃ ግንባታ"},{"value":"books","labelAm":"ለመጻሕፍት ሕትመት"}],"required":true},{"name":"pledgeFrequency","type":"radio","labelAm":"የክፍያ ሁኔታ","labelEn":"Frequency","options":[{"value":"monthly","labelAm":"ወርሃዊ"},{"value":"one_time","labelAm":"የአንድ ጊዜ"}],"required":true},{"name":"pledgedAmount","type":"number","labelAm":"የተገባው መጠን (ብር)","labelEn":"Amount","required":true,"validation":{"min":100}},{"name":"pledgeStartDate","type":"date","labelAm":"የሚጀመርበት ቀን","labelEn":"Start Date","required":true}],"titleAm":"የስእለትና የልማት ቃል ኪዳን መመዝገቢያ ቅጽ","titleEn":"Pledge & Contribution Commitment Form"}', 'open', '2026-12-31T23:59:59.000Z', '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-13T07:44:12.244Z', '2026-10-13T07:44:12.244Z', 0);
INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `createdBy`, `createdAt`, `updatedAt`, `allowOneResponsePerMember`) VALUES ('a7e8e76f-5295-4ae0-8e2f-69bec08ef42e', 'የበጎ ፈቃድ አገልግሎት ምዝገባ ቅጽ', 'በሰንበት ትምህርት ቤቱ በተለያዩ የበጎ አድራጎት፣ የልማትና የማኅበራዊ አገልግሎት ዘርፎች ለመሳተፍ የተዘጋጀ ቅጽ', '{"fields":[{"name":"volunteerName","type":"text","labelAm":"የበጎ ፈቃደኛው ስም","labelEn":"Name","required":true},{"name":"phone","type":"text","labelAm":"ስልክ ቁጥር","labelEn":"Phone","required":true},{"name":"profession","type":"text","labelAm":"የትምህርት ደረጃ ወይም ሙያ","labelEn":"Profession","required":true},{"name":"interestedMinistries","type":"checkbox","labelAm":"ለማገልገል የሚፈልጓቸው ዘርፎች","labelEn":"Ministries","options":[{"value":"media","labelAm":"ሚዲያና ቴክኖሎጂ"},{"value":"charity","labelAm":"መርጃ ማዕድ"}],"required":true},{"name":"experienceSummary","type":"textarea","labelAm":"ቀደም ሲል የነበሩዎት ልምዶች","labelEn":"Experience","required":true,"validation":{"minLength":10}},{"name":"hasConfessionFather","type":"radio","labelAm":"የንስሐ አባት አሎት?","labelEn":"Confession Father","options":[{"value":"yes","labelAm":"አዎ አለኝ"},{"value":"no","labelAm":"የለኝም"}],"required":true}],"titleAm":"የበጎ ፈቃድ አገልግሎት ምዝገባ ቅጽ","titleEn":"Volunteer Ministry Sign-Up Form"}', 'open', '2026-12-31T23:59:59.000Z', '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-13T07:44:12.155Z', '2026-10-13T07:44:12.155Z', 0);
