INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `createdBy`, `createdAt`, `updatedAt`, `allowOneResponsePerMember`) VALUES ('d0a1274c-0788-499c-a55c-8f453a179e7c', 'የበጎ ፈቃድ አገልግሎት ምዝገባ ቅጽ', 'በሰንበት ትምህርት ቤቱ በተለያዩ የበጎ አድራጎት፣ የልማትና የማኅበራዊ አገልግሎት ዘርፎች ለመሳተፍ የተዘጋጀ ቅጽ', '{"fields":[{"name":"volunteerName","type":"text","labelAm":"የበጎ ፈቃደኛው ሙሉ ስም","labelEn":"Volunteer Full Name","required":true,"validation":{"minLength":3}},{"name":"phone","type":"text","labelAm":"ስልክ ቁጥር","labelEn":"Phone Number","required":true,"validation":{"minLength":9}},{"name":"profession","type":"text","labelAm":"የትምህርት ደረጃ ወይም ሙያዊ መስክ","labelEn":"Education or Profession","required":true},{"name":"interestedMinistries","type":"checkbox","labelAm":"ለማገልገል የሚፈልጓቸው ዘርፎች (ቢያንስ አንድ ይምረጡ)","labelEn":"Interested Ministry Fields","options":[{"value":"media","labelAm":"ሚዲያ፣ ድረ-ገጽና ቴክኖሎጂ","labelEn":"Media & Technology"},{"value":"children","labelAm":"የሕፃናትና ታዳጊዎች ማስተማር","labelEn":"Children Teaching"},{"value":"cleaning_order","labelAm":"የቤተ መቅደስ ጽዳትና ሥርዓት ማስከበር","labelEn":"Sanctuary Care & Protocol"},{"value":"medical_aid","labelAm":"የሕክምናና የመጀመሪያ እርዳታ ድጋፍ","labelEn":"First Aid & Health Ministry"},{"value":"charity","labelAm":"የአረጋውያንና ችግረኞች መርጃ ማዕድ","labelEn":"Charity & Food Outreach"}],"required":true,"validation":{"minSelected":1}},{"name":"availableDays","type":"checkbox","labelAm":"የሚያገለግሉባቸው አመቺ ቀናት","labelEn":"Available Days","options":[{"value":"sat_afternoon","labelAm":"ቅዳሜ ከሰዓት","labelEn":"Saturday Afternoon"},{"value":"sun_morning","labelAm":"እሑድ ጠዋት","labelEn":"Sunday Morning"},{"value":"sun_afternoon","labelAm":"እሑድ ከሰዓት","labelEn":"Sunday Afternoon"},{"value":"holidays","labelAm":"በዓበይት በዓላት ቀናት","labelEn":"On Major Feast Days"}],"required":true,"validation":{"minSelected":1}},{"name":"experienceSummary","type":"textarea","labelAm":"ቀደም ሲል የነበሩዎት የበጎ ፈቃድ ወይም የአገልግሎት ልምዶች","labelEn":"Previous Volunteer or Service Experience","required":true,"validation":{"maxLength":1000,"minLength":10}},{"name":"hasConfessionFather","type":"radio","labelAm":"የንስሐ አባት አሎት?","labelEn":"Do you have a confession father?","options":[{"value":"yes","labelAm":"አዎ አለኝ","labelEn":"Yes"},{"value":"no","labelAm":"እስካሁን የለኝም","labelEn":"Not yet"}],"required":true},{"name":"recommendationLetter","type":"file","labelAm":"የድጋፍ ወይም የደብር ደብዳቤ (ካለዎት)","labelEn":"Recommendation Letter (Optional)","required":false}],"titleAm":"የበጎ ፈቃድ አገልግሎት ምዝገባ ቅጽ","titleEn":"Volunteer Ministry Sign-Up Form","descriptionAm":"ለቤተ ክርስቲያንና ለወገን በበጎ ፈቃድ ለማገልገል ይመዝገቡ","descriptionEn":"Register to serve the church and community as a volunteer"}', 'open', NULL, '1a7ec929-3f61-4173-87d7-3d0ba1961c3e', '2026-10-13T08:12:58.120Z', '2026-10-13T08:12:58.120Z', 0);
INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `createdBy`, `createdAt`, `updatedAt`, `allowOneResponsePerMember`) VALUES ('d13e05d8-95fe-4782-a6ed-9138de85816e', 'የአባላት ዓመታዊ የእርካታ ዳሰሳ ቅጽ (አንድ ምላሽ ብቻ)', 'በአንድ አባል አንድ ጊዜ ብቻ የሚሞላ የዳሰሳ ቅጽ', '{"fields":[{"name":"score","type":"number","labelAm":"የእርካታ ነጥብ (ከ 1 እስከ 10)","labelEn":"Satisfaction Score","required":true,"validation":{"max":10,"min":1}},{"name":"feedback","type":"text","labelAm":"አስተያየት","labelEn":"Feedback","required":false}]}', 'open', NULL, '1a7ec929-3f61-4173-87d7-3d0ba1961c3e', '2026-10-13T08:02:37.940Z', '2026-10-13T08:02:37.940Z', 1);
