INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `createdBy`, `createdAt`, `updatedAt`, `allowOneResponsePerMember`) VALUES ('d5e17a9a-b521-4702-8bea-86dd5557e6a2', 'የልዩ ጉባኤና መርሐ ግብር ምዝገባ ቅጽ', 'በዓመታዊ ጉባኤያት፣ ሲምፖዚየሞችና መንፈሳዊ ጉዞዎች ላይ ለመሳተፍ የተዘጋጀ የምዝገባ ቅጽ', '{"fields":[{"name":"participantName","type":"text","labelAm":"የተሳታፊ ሙሉ ስም","labelEn":"Full Name","required":true},{"name":"phone","type":"text","labelAm":"ስልክ ቁጥር","labelEn":"Phone Number","required":true},{"name":"ageGroup","type":"radio","labelAm":"የዕድሜ ክልል","labelEn":"Age Group","options":[{"value":"21-30","labelAm":"ከ 21 - 30 ዓመት"},{"value":"31-50","labelAm":"ከ 31 - 50 ዓመት"}],"required":true},{"name":"parishChurch","type":"text","labelAm":"የመጡበት ደብር","labelEn":"Parish","required":true},{"name":"attendanceDays","type":"checkbox","labelAm":"የሚገኙባቸው ቀናት","labelEn":"Days","options":[{"value":"ቅዳሜ","labelAm":"ቅዳሜ"},{"value":"እሑድ","labelAm":"እሑድ"}],"required":true},{"name":"transportation","type":"dropdown","labelAm":"የትራንስፖርት አገልግሎት","labelEn":"Transport","options":[{"value":"ካዛንቺስ","labelAm":"ከካዛንቺስ"},{"value":"በራሴ","labelAm":"በራሴ"}],"required":true}],"titleAm":"የልዩ ጉባኤና መርሐ ግብር ምዝገባ ቅጽ","titleEn":"Special Event & Conference Registration Form"}', 'open', '2026-11-30T23:59:59.000Z', '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-13T07:44:12.072Z', '2026-10-13T07:44:12.072Z', 0);
INSERT INTO `forms` (`id`, `title`, `description`, `formSchema`, `status`, `openUntil`, `createdBy`, `createdAt`, `updatedAt`, `allowOneResponsePerMember`) VALUES ('e748d740-e3fa-4ba5-a9bd-86804aa046d3', 'የአባልነት እድሳት ቅጽ (ዓመታዊ)', 'በአዕማደ ሰላም ሰንበት ትምህርት ቤት የአገልግሎት አባላት ዓመታዊ ምዝገባ ማደሻና ቃል ኪዳን ማረጋገጫ ቅጽ', '{"fields":[{"name":"fullName","type":"text","labelAm":"ሙሉ ስም (ከነ አያት)","labelEn":"Full Name","required":true,"validation":{"minLength":3}},{"name":"baptismalName","type":"text","labelAm":"የክርስትና ስም","labelEn":"Baptismal Name","required":true},{"name":"memberNo","type":"text","labelAm":"የአባልነት መለያ ቁጥር","labelEn":"Member ID","required":true},{"name":"phone","type":"text","labelAm":"ስልክ ቁጥር","labelEn":"Phone Number","required":true},{"name":"currentDepartment","type":"dropdown","labelAm":"ያሉበት የአገልግሎት ክፍል","labelEn":"Department","options":[{"value":"ትምህርት","labelAm":"የትምህርት ክፍል"},{"value":"መዝሙር","labelAm":"የመዝሙር ክፍል"},{"value":"ልማት","labelAm":"የልማት ክፍል"}],"required":true},{"name":"confessionFather","type":"text","labelAm":"የንስሐ አባት ስም","labelEn":"Confession Father","required":true},{"name":"renewalYear","type":"number","labelAm":"የእድሳት ዓ.ም","labelEn":"Renewal Year","required":true,"validation":{"max":2030,"min":2015}},{"name":"renewDate","type":"date","labelAm":"የማደሻ ቀን","labelEn":"Renewal Date","required":true},{"name":"serviceCommitment","type":"radio","labelAm":"የአገልግሎት ቁርጠኝነት","labelEn":"Service Commitment","options":[{"value":"ሙሉ ጊዜ","labelAm":"ሙሉ ጊዜ"},{"value":"በከፊል","labelAm":"በከፊል"}],"required":true},{"name":"agreement","type":"checkbox","labelAm":"የሰንበት ት/ቤቱን መተዳደሪያ ደንብ አከብራለሁ","labelEn":"I agree to bylaws","required":true}],"titleAm":"የአባልነት እድሳት ቅጽ","titleEn":"Membership Renewal Form"}', 'open', '2026-12-31T23:59:59.000Z', '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-13T07:44:11.993Z', '2026-10-13T07:44:11.993Z', 1);
