INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('039443d6-70c1-4bff-acc0-51c1990d74a4', 'አቤቱ ይቅር በለን', 'አቤቱ እንደ ቸርነትህ ይቅር በለን፤ እንደ ምህረትህም ብዛት በደላችንን ደምስስ።', 6, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.000Z', '2026-10-12T12:37:42.000Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('0df4e340-b7be-47f7-a43d-65818df90ad9', 'እግዚአብሔር ብርሃኔና መድኃኒቴ ነው', 'እግዚአብሔር ብርሃኔና መድኃኒቴ ነው፤ የሚያስፈራኝ ማን ነው?', 3, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.097Z', '2026-10-12T12:37:42.097Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('1fbd4262-7fa9-410a-b3c4-1e13bfc297e4', 'በጾም በጸሎት እንትጋ', 'በጾም በጸሎት ወደ አምላክ እንቅረብ፤ የልብ ንጽሕናን ከእርሱ እንቀበል።', 6, 'ዘማሪት ፋንቱ', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.385Z', '2026-10-12T12:37:42.385Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('26972c2c-2216-41b5-846e-b6cc02c5027e', 'ተወልደ ኢየሱስ በቤተ ልሔም', 'ተወልደ ኢየሱስ በቤተ ልሔም ዘይሁዳ አማኑኤል ተወልደልን', 8, 'አዕማደ ሰላም መዘምራን', '/uploads/mezmurs/audio/7eb076ae-2f31-4584-b0d8-3f2601fa8f4d.mp3', '/uploads/mezmurs/video/5199963a-5c3b-4a28-ab1b-bb166ba41bd3.mp4', 1, '8b862aa1-dbc0-4d34-a1c6-614b2127948e', '2026-10-13T07:02:11.987Z', '2026-10-13T07:02:12.355Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('2f95a582-a02f-4224-94db-270987c4989f', 'መስቀል ኃይላችን ነው', 'መስቀል ኃይላችን ነው መስቀል ቤዛችን ነው፤ በክርስቶስ መስቀል ድኅነት አግኝተናል።', 3, 'ዘማሪ ዲ/ን ቴዎድሮስ', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:41.927Z', '2026-10-12T12:37:41.927Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('5343ae88-86bf-4df9-a83f-b814b5ffa8d2', 'የውስጥ ልምምድ መዝሙር', 'ለጥናት ብቻ የተዘጋጀ ሚስጥራዊ ግጥም', 8, NULL, NULL, NULL, 0, '8b862aa1-dbc0-4d34-a1c6-614b2127948e', '2026-10-13T07:02:12.110Z', '2026-10-13T07:02:12.110Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('61ef260b-5db5-4ba0-a4ec-08c657f378f8', 'ሩፋኤል ፈዋሽ መልአክ', 'ሕመምን አርቆ ጤናን የሚያድል፤ ሩፋኤል ሊቀ መላእክት ይቁም ከጎናችን።', 4, 'ዘማሪ ዲ/ን አስቻለው', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.231Z', '2026-10-12T12:37:42.231Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('6a11ae25-7ba9-4446-9372-d8737db1ceb6', 'እንኳን አደረሳችሁ ለብርሃነ መስቀሉ', 'መስቀል አበራ በደመና፤ ደስ ይበለን በሃይማኖት ሆነን ሁላችን በአንድነት።', 7, 'ሊቀ መዘምራን ኪነጥበብ', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.022Z', '2026-10-12T12:37:42.022Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('75107c11-da78-4bd1-a26e-e4539d8d457a', 'ሰላም ለኪ ማርያም ድንግል', 'ሰላም ለኪ ማርያም ድንግል ንጽሕት፤ በጸሎትሽ ጠብቂን ከመከራ ሕይወት።', 2, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:41.897Z', '2026-10-12T12:37:41.897Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('7815de9b-89c2-4ed2-9da7-271e623e3e36', 'ማርያም ድንግል እናቴ', 'ማርያም ድንግል እናቴ አንቺ ነሽ ዋስትናዬ፤ ባንቺ አማላጅነት ይብራ ዘመኔ።', 2, 'ዘማሪት ምርትነሽ ጥላሁን', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.072Z', '2026-10-12T12:37:42.072Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('87127610-c914-44a4-962c-b452f5191e81', 'በቀራንዮ መስቀል ላይ', 'በቀራንዮ ተሰቅሎ አዳነን፤ በክቡር ደሙ ፈሳሽነት ከኃጢአት አነጻን።', 3, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.171Z', '2026-10-12T12:37:42.171Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('8a2af92f-a118-42c1-820e-561b30a52218', 'እልል በሉ በአንድነት', 'እልል በሉ በአንድነት ለእግዚአብሔር ክብር፤ ድንቅ ሥራውን በምድር ላይ አሳይቷልና።', 7, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.436Z', '2026-10-12T12:37:42.436Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('a0f03074-aa92-4527-971b-056158b951f0', 'ጻድቁ አባታችን ተክለ ሃይማኖት', 'ተክለ ሃይማኖት ጸሎትህ አይለየን፤ በምልጃህ ጸንተን በበረከት እንኑር።', 5, 'ዘማሪት ፋንቱ ወልዴ', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:41.971Z', '2026-10-12T12:37:41.971Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('a15a6a19-abe4-4391-bcce-680fe6722b4b', 'ሥላሴን አመስግኑ', 'አንድነቱን ሳንለይ ሦስትነቱን ሳንቀላቅል፤ ለአብ ለወልድ ለመንፈስ ቅዱስ ክብር ምስጋና ይሁን።', 1, 'ዘማሪ ዲ/ን ልዑለቃል', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.045Z', '2026-10-12T12:37:42.045Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('ad9b739f-d474-486a-9cb7-416a800097ca', 'ነፍሴ ሆይ እግዚአብሔርን ባርኪ', 'ነፍሴ ሆይ እግዚአብሔርን ባርኪ፤ ምስጋናውንም አትርሺ።', 1, 'ዘማሪ ዲ/ን ቴዎድሮስ', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.298Z', '2026-10-12T12:37:42.298Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('c84cd26b-8500-4ce0-94d3-b9c8f2746f5e', 'ቅዱስ ሚካኤል ሊቀ መላእክት', 'ቅዱስ ሚካኤል ቆሟል በፊታችን፤ ታዳጊ መልአክ ነው ለመከራችን።', 4, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:41.950Z', '2026-10-12T12:37:41.950Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('e0f9fc6f-a52a-432a-8a5f-a49e0b72db11', 'ገብርኤል አብሳሪው', 'ብስራተ ሰላምን ይዞ የመጣው፤ ገብርኤል መልአከ እግዚአብሔር ነው።', 4, 'ዘማሪ ይስሐቅ', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.123Z', '2026-10-12T12:37:42.123Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('e3f63b9c-ae40-4361-b91b-fb1f6a2f0a9b', 'ቸርነትህ ብዙ ነው', 'ቸርነትህ ብዙ ነው ምህረትህም አያልቅም፤ አቤቱ አምላካችን ስምህ የተመሰገነ ይሁን።', 1, 'ሊቀ መዘምራን ቴዎድሮስ ዮሴፍ', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:41.866Z', '2026-10-12T12:37:41.866Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('ef5a9806-05fc-4a56-99c3-42895613a7e8', 'ጊዮርጊስ ኃያል ሰማዕት', 'ጊዮርጊስ ተጋዳይ በፈተና የጸና፤ አክሊለ ክብርን ተቀዳጀ በጽናት።', 5, 'ዘማሪ ዲ/ን ዘርዓያዕቆብ', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.148Z', '2026-10-12T12:37:42.148Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('f164e8d1-4b89-4059-8189-f6c5bb05eab9', 'ጽዮን ሆይ ደስ ይበልሽ', 'ጽዮን ሆይ ደስ ይበልሽ ንጉሥሽ ይመጣል፤ ጻድቅና አዳኝ የሆነው ጌታ።', 7, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.348Z', '2026-10-12T12:37:42.348Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('f89e53ac-a0b7-4f14-95b1-b150f850ec73', 'ድንግል ሆይ ስምሽን ስጠራ', 'ስምሽን ስጠራ ልቤ ይረካል፤ በአማላጅነትሽ ጥላ ከለላ ያገኛል።', 2, 'ዘማሪት ሲስተር ልኬለሽ', NULL, NULL, 1, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.205Z', '2026-10-12T12:37:42.205Z');
