INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('2762aa83-9447-41fb-b4c2-2f07b92e62d3', 'bible_reading', 'የዕለቱ የቅዱስ ወንጌል ንባብ', '«እኔ የመንገድ እውነትና ሕይወት ነኝ፤ በእኔ በቀር ወደ አብ የሚመጣ ማንም የለም» - ዮሐንስ ፲፬:፮', NULL, 0, '2026-10-12T12:37:42.537Z', NULL, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.537Z', '2026-10-12T12:37:42.537Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('389ca9ae-8ffe-40e8-8893-dfeb99961979', 'urgent', 'አስቸኳይ ማስታወቂያ፡ ልዩ የጸሎትና የምልጃ መርሐ ግብር', 'ለሁሉም የሰንበት ትምህርት ቤት አባላት፡ በመጪው ዓርብ ከምሽቱ 11:30 ጀምሮ ልዩ የጋራ ጸሎት ይደረጋል፤ ሳያቋርጡ ይገኙ።', NULL, 1, '2026-10-12T12:37:42.626Z', NULL, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.626Z', '2026-10-12T12:37:42.626Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('5efcae7a-2ad6-4ee4-acb8-5d83f779923b', 'news', 'የአዲስ ተማሪዎች ምዝገባ ተጀመረ', 'ለ2019 ዓ.ም የትምህርት ዘመን ከደረጃ ፩ እስከ ፬ የአዲስ ተማሪዎች ምዝገባ በይፋ ተከፍቷል።', NULL, 0, '2026-10-12T12:37:42.677Z', NULL, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.677Z', '2026-10-12T12:37:42.677Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('616e40aa-7bc8-48b7-937a-fbd7ed972317', 'news', 'የመዘምራን ክፍል አዲስ አልበም ዝግጅት', 'የመዝሙር ክፍሉ አዲስ መንፈሳዊ ያሬዳዊ የዝማሬ አልበም ለማዘጋጀት ልምምድ ጀምሯል።', NULL, 0, '2026-10-12T12:37:42.747Z', NULL, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.747Z', '2026-10-12T12:37:42.747Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('7ec7e257-d8ff-437c-85fb-fa8e0592e38f', 'sinksar', 'የዕለቱ ስንክሳር፡ ጥቅምት ፪', 'በዚህች ዕለት የከበሩ ጻድቃንና ሰማዕታት መታሰቢያቸው ሆነ፤ ጸሎታቸውና ምልጃቸው ከሁላችን ጋር ይሁን።', NULL, 0, '2026-10-12T12:37:42.489Z', NULL, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.489Z', '2026-10-12T12:37:42.489Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('9c216ce4-bfcd-4877-9f58-ce1f1acc64b7', 'saint_of_day', 'የዕለቱ ቅዱስ፡ አባ ጳውሊ ታላቁ ገዳማዊ', 'የገዳማዊ ሕይወት ቀዳሚ የሆኑት አባ ጳውሊ በበረሃ የኖሩበት ገድልና ድንቅ መንፈሳዊ ተጋድሎ።', NULL, 0, '2026-10-12T12:37:42.562Z', NULL, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.562Z', '2026-10-12T12:37:42.562Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('d0f013f8-0068-4f59-b96d-6dee262576ac', 'sinksar', 'የጥቅምት ወር የበዓላት ማውጫ', 'በዚህ ወር የሚከበሩ ዓበይትና ንዑሳን የቅዱሳን በዓላት ዝርዝርና መርሐ ግብራቸው።', NULL, 0, '2026-10-12T12:37:42.725Z', NULL, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.725Z', '2026-10-12T12:37:42.725Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('dd608c68-eafc-4743-8e50-fca707ac1a8a', 'teaching', 'የሰንበት ትምህርት ቤት አስፈላጊነት በዘመናችን', 'ሰንበት ትምህርት ቤት የቤተ ክርስቲያን የጀርባ አጥንት ናት። ሕፃናትና ወጣቶች በእውነተኛው ሃይማኖትና ምግባር የሚታነጹበት ማዕከል ናት።', NULL, 0, '2026-10-12T12:37:42.597Z', NULL, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.597Z', '2026-10-12T12:37:42.597Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('f2c12547-2f92-4c22-b998-89b173257568', 'teaching', 'ስለ አሥራትና በኩራት ትምህርት', '«በቤቴ ውስጥ መብል እንዲሆን አሥራቱን ሁሉ ወደ ጎተራ አግቡ» - ሚልክያስ ፫:፲። የክርስትና የልግስና መርሆዎች።', NULL, 0, '2026-10-12T12:37:42.700Z', NULL, '9ea2a0d5-f67a-4e33-bdbe-8ee5d369b894', '2026-10-12T12:37:42.700Z', '2026-10-12T12:37:42.700Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('f2c75c91-6626-49db-92d5-9d5e8e4db3b1', 'sinksar', 'የዕለቱ ስንክሳር - ጥቅምት ፫', 'በዚህች ዕለት አባ ጽጌ ድንግል እና ቅዱሳን ሰማዕታት ይታሰባሉ።', '/uploads/posts/40a86de1-1afb-4580-91c2-38a0d221a42d.webp', 0, '2026-10-13T07:00:13.568Z', '2026-10-13T07:02:03.568Z', '8b862aa1-dbc0-4d34-a1c6-614b2127948e', '2026-10-13T07:02:12.771Z', '2026-10-13T07:02:13.602Z');
